    for field in ("tenant_id", "operator_id", "path", "request_body"):
        value = descriptor.get(field)
        if not isinstance(value, str):
            return False
    if not descriptor.get("tenant_id"):
        return False
    kind = descriptor.get("kind")
    action = descriptor.get("action")
    write_set = descriptor.get("write_set")
    if kind is None:
        if not allow_undescribed:
            return False
        if action is not None or write_set:
            return False
    else:
        if kind not in _KIND_ACTIONS or action != _KIND_ACTIONS[kind]:
            return False
        if not ArtifactStore._valid_write_set_shape(kind, write_set):
            return False
    # A read-only kind (encrypt) mints nothing: any handle, provision
    # journal, batch snapshot, restore marker or policy fact on its mirror
    # is by construction an inconsistency.
    if kind in _READ_ONLY_KINDS:
        if descriptor.get("handles"):
            return False
        if descriptor.get("journal") is not None:
            return False
        if descriptor.get("snapshot") is not None:
            return False
        if descriptor.get("empty_marker") is not None:
            return False
        if descriptor.get("policy"):
            return False
    journal = descriptor.get("journal")
    if journal is not None and journal != operation_id:
        return False
    snapshot = descriptor.get("snapshot")
    if snapshot is not None:
        if snapshot != operation_id or kind != "batch_rotate":
            return False
    empty_marker = descriptor.get("empty_marker")
    if empty_marker is not None and not isinstance(empty_marker, str):
        return False
    if not isinstance(descriptor.get("policy"), bool):
        return False
    handles = descriptor.get("handles")
    if not isinstance(handles, list):
        return False
    seen = set()
    for entry in handles:
        if not isinstance(entry, dict):
            return False
        provider_id = entry.get("provider_id")
        handle = entry.get("handle")
        if (
            not isinstance(provider_id, str)
            or not provider_id
            or not isinstance(handle, str)
            or not handle
        ):
            return False
        pair = (provider_id, handle)
        if pair in seen:
            return False
        seen.add(pair)
    return True

@staticmethod
def _valid_write_set_shape(kind: str, write_set) -> bool:
    """The kind's exact write-set shape (unique canonical UUID4s)."""
    if not isinstance(write_set, list):
        return False
    seen = set()
    for key_id in write_set:
        if not _is_key_id(key_id) or key_id in seen:
            return False
        seen.add(key_id)
    if kind in ("rotate", "import", "encrypt") and len(seen) != 1:
        return False
    if kind == "batch_rotate" and not seen:
        return False
    return True

@staticmethod
def _details_correspond(descriptor: dict, record) -> bool:
    """Whether the operation record's durable details match the mirror.

    The kind/action must correspond to the exact ``key_id`` (rotate/
    import), ``items`` set (batch rotation) or ``key_ids`` plus policy
    flag (restore) the executor persisted in ``operations/<id>.json``.
    A mirror that was never described has nothing yet to correspond.
    """
    kind = descriptor.get("kind")
    if kind is None:
        return True
    details = getattr(record, "details", None)
    if not isinstance(details, dict) or details.get("kind") != kind:
        return False
    write_set = descriptor.get("write_set") or []
    if kind in ("rotate", "import", "encrypt"):
        return details.get("key_id") == (write_set[0] if write_set else None)
    if kind == "batch_rotate":
        items = details.get("items")
        if not isinstance(items, list):
            return False
        item_keys = set()
        for item in items:
            if not isinstance(item, dict) or not _is_key_id(
                item.get("key_id")
            ):
                return False
            item_keys.add(item["key_id"])
        return item_keys == set(write_set)
    key_ids = details.get("key_ids")
    if not isinstance(key_ids, list) or sorted(key_ids) != sorted(write_set):
        return False
    return bool(details.get("policy_restored")) == bool(
        descriptor.get("policy")
    )

def _binding_matches(self, descriptor: dict, record) -> bool:
    """Whether the mirror is the SAME attempt as the operation record.

    Compares the full binding (tenant/operator/path/canonical request),
    requires an internally consistent descriptor, and -- once the mirror
    is described -- requires the record's durable details to name the
    exact same kind, key_id/items, write set and policy fact.
    """
    if descriptor.get("operation_id") != record.operation_id:
        return False
    for field in ("tenant_id", "operator_id", "path", "request_body"):
        if descriptor.get(field) != getattr(record, field):
            return False
    if not self._descriptor_consistent(descriptor, allow_undescribed=True):
        return False
    if not self._details_correspond(descriptor, record):
        return False
    return True

@staticmethod
def _event_confirms(descriptor: dict, event) -> bool:
    """Whether a durable event is exactly this mirror's commit event.

    The event id is the operation id by construction; action and tenant
    must additionally agree with the mirror. A rejected event or an
    action/tenant mismatch never confirms a commit.
    """
    if event is None or event.outcome != audit_mod.OUTCOME_SUCCESS:
        return False
    tenant = descriptor.get("tenant_id")
    if tenant is not None and event.tenant_id != tenant:
        return False
    kind = descriptor.get("kind")
    expected = descriptor.get("action") or _KIND_ACTIONS.get(kind)
    if expected is None:
        # The mirror never recorded which action the attempt commits
        # (crash between create and describe): a durable event cannot be
        # confirmed as THIS attempt's commit -- action agreement is
        # unprovable, so never clean on it.
        return False
    return event.action == expected

def _rejected_event_matches(self, descriptor: dict, record, event) -> bool:
    """Whether a durable REJECTED terminal event belongs to this mirror.

    A rejection commits no write set, but its event must still name the
    operation and carry the mirror's action and tenant; rotate/import
    rejections project the one write-set key while batch/restore events
    project no key. When the record staged its audit descriptor / result
    before the append, those durable facts must agree with the event and
    the staged response must be a refusal (never a 201). Anything less
    leaves the evidence parked.
    """
    if event is None or event.outcome != audit_mod.OUTCOME_REJECTED:
        return False
    if descriptor.get("kind") is None:
        return False
    if event.action != descriptor.get("action"):
        return False
    if event.tenant_id != descriptor.get("tenant_id"):
        return False
    kind = descriptor.get("kind")
    write_set = descriptor.get("write_set") or []
    if kind in ("rotate", "import", "encrypt"):
        if event.key_id != (write_set[0] if write_set else None):
            return False
    elif event.key_id is not None:
        return False
    details = getattr(record, "details", None)
    if isinstance(details, dict):
        audit_desc = details.get("audit")
        if isinstance(audit_desc, dict):
            if audit_desc.get("action") not in (None, event.action):
                return False
            if audit_desc.get("outcome") not in (
                None, audit_mod.OUTCOME_REJECTED
            ):
                return False
            if audit_desc.get("tenant_id") not in (None, event.tenant_id):
                return False
        result = details.get("result")
        if isinstance(result, dict) and result.get("http_status") == 201:
            # A staged 201 response cannot share an id with a rejection.
            return False
    return True

def _staged_success_response_backed(
    self, descriptor: dict, record
) -> bool:
    """Whether a staged 201 response is backed by the committed write set.

    Startup settlement uses this when the operation record persisted its
    exact success response before the commit-point append: the on-disk
    committed state must actually support that response (the named
    versions exist; a restore's key set and policy flag match). Records
    without a staged response (older bindings, crafted recovery scenes)
    skip this and rely on the artifact checks alone.
    """
    details = getattr(record, "details", None)
    if not isinstance(details, dict):
        return True
    result = details.get("result")
    if not isinstance(result, dict):
        return True
    http_status = result.get("http_status")
    response = result.get("response")
    if http_status is None and response is None:
        return True
    if not isinstance(response, dict):
        return False
    kind = descriptor.get("kind")
    tenant_id = descriptor.get("tenant_id")
    write_set = descriptor.get("write_set") or []
    # Mutating operations stage a 201; the read-only encrypt stages a 200.
    allowed_status = 200 if kind in _READ_ONLY_KINDS else 201
    if http_status != allowed_status:
        return False
    if kind in ("rotate", "import"):
        key_id = write_set[0] if write_set else None
        if response.get("key_id") != key_id:
            return False
        key = self.key_store._read_record(self.key_store._path_for(key_id))
        if key is None or key.tenant_id != tenant_id:
            return False
        if kind == "rotate":
            version = response.get("version")
            if not isinstance(version, int) or key.get_version(version) is None:
                return False
    elif kind == "batch_rotate":
        items = response.get("items")
        if not isinstance(items, list):
            return False
        response_keys = set()
        for item in items:
            if not isinstance(item, dict):
                return False
            key_id = item.get("key_id")
            if not _is_key_id(key_id):
                return False
            response_keys.add(key_id)
            key = self.key_store._read_record(
                self.key_store._path_for(key_id)
            )
            if key is None or key.tenant_id != tenant_id:
                return False
            version = item.get("version")
            if not isinstance(version, int) or key.get_version(version) is None:
                return False
        if response_keys != set(write_set):
            return False
    elif kind == "encrypt":
        # The read-only encrypt creates nothing: the key must still exist
        # for the mirror's tenant and the staged envelope must name that
        # same key and one of its existing versions. The envelope bytes
        # themselves are opaque -- only structural metadata is checked.
        from . import envelope as envelope_mod

        key_id = write_set[0] if write_set else None
        if response.get("format") != envelope_mod.FORMAT:
            return False
        if response.get("operation_id") != descriptor.get("operation_id"):
            return False
        token = response.get("envelope")
        if not isinstance(token, str) or not token:
            return False
        try:
            opened = envelope_mod.decode_envelope(token)
        except Exception:
            return False
        if opened.key_id != key_id:
            return False
        key = self.key_store._read_record(self.key_store._path_for(key_id))
        if key is None or key.tenant_id != tenant_id:
            return False
        if key.get_version(opened.version) is None:
            return False
    elif kind == "restore":
        key_ids = response.get("key_ids")
        if not isinstance(key_ids, list) or sorted(key_ids) != sorted(
            write_set
        ):
            return False
        if response.get("policy_restored") != bool(descriptor.get("policy")):
            return False
        for key_id in write_set:
            key = self.key_store._read_record(
                self.key_store._path_for(key_id)
            )
            if key is None or key.tenant_id != tenant_id:
                return False
    return True

def _committed_state_verified(self, descriptor: dict) -> bool:
    """Verify the committed write set and every surviving reference.

    Every write-set key file must exist, belong to the mirror's tenant,
    carry no unresolved pending marker of this operation and own every
    (provider_id, handle) the mirror recorded; a restore that carried a
    policy leaves the tenant's committed policy document, and an empty
    restore leaves its finalized (event-cleared) marker. The provision
    journal and a batch snapshot are post-commit housekeeping and must
    already be gone. Finally every surviving on-disk reference must be
    cross-consistent with the mirror (a missing/corrupt/duplicate/extra
    reference keeps the mirror for the next open).
    """
    if not self._descriptor_consistent(descriptor, allow_undescribed=False):
        return False
    operation_id = descriptor["operation_id"]
    journal_id = descriptor.get("journal") or operation_id
    if os.path.exists(self.key_store._provision_path(journal_id)):
        return False
    if descriptor.get("snapshot") and os.path.exists(
        self.key_store._batch_snapshot_path(descriptor["snapshot"])
    ):
        return False
    kind = descriptor.get("kind")
    tenant_id = descriptor.get("tenant_id")
    owned = set()
    for key_id in descriptor.get("write_set", []):
        record = self.key_store._read_record(self.key_store._path_for(key_id))
        if record is None or record.tenant_id != tenant_id:
            return False
        marker = getattr(record, "pending_event", None)
        if isinstance(marker, dict) and self._marker_event_id(
            marker
        ) == operation_id:
            return False
        for ver in record.versions:
            owned.add((ver.provider_id, ver.handle))
    expected = {
        (entry.get("provider_id"), entry.get("handle"))
        for entry in descriptor.get("handles", [])
        if isinstance(entry, dict)
    }
    if not expected.issubset(owned):
        return False
    if kind == "restore" and not self._committed_restore_extras_verified(
        descriptor
    ):

def _resolve_committed_operation(store, policy_store, record, event):
    """Rebuild the terminal response of a committed-but-unfinished operation.

    Runs during startup recovery after the key/restore outbox recovery has
    made the mutation durable. The audit event named after the operation_id
    is the durable fact: a ``success`` event rebuilds the original 201
    response, while a ``rejected`` event rebuilds the exact 403/404/409
    terminal (its state, error body and audit projection) from the recorded
    action/key_id and the current tenant state. Returns
    ``(http_status, response)``.
    """
    op_id = record.operation_id
    details = record.details or {}
    kind = details.get("kind")
    tenant_id = record.tenant_id
    operator_id = record.operator_id

    def error(status: int, message: str):
        return status, {"error": message, "operation_id": op_id}

    if event.outcome == audit_mod.OUTCOME_REJECTED:
        action = event.action
        terminal = details.get("terminal")
        # A batch rotation is AUTHORIZED as rotate even though its audit
        # action is batch_rotate; map back for the legacy no-terminal policy
        # reconstruction below.
        policy_action = (
            audit_mod.ACTION_ROTATE
            if action == audit_mod.ACTION_BATCH_ROTATE
            else action
        )

        def message_for(status: int) -> str:
            if status == 403:
                return "action not permitted by policy"
            if status == 409:
                if kind == "restore":
                    return "backup target already contains this data"
                return "key_id already exists for this tenant"
            if kind == "restore":
                return "tenant backup not found"
            return "key not found"

        # The original terminal status is persisted with the event: replay it
        # verbatim, so a policy change or a state change after the crash can
        # never turn a 403 into a 404/409 or vice versa.
        if terminal in (403, 404, 409):
            return error(terminal, message_for(terminal))

        # Older records without the stashed terminal: infer once from the
        # durable action and the current state.
        # A policy denial outranks existence: it is reconstructed whenever the
        # tenant's policy currently rejects this operator/action.
        if not policy_store.is_allowed(tenant_id, policy_action, operator_id):
            return error(403, message_for(403))
        if kind == "restore":
            # A same-tenant conflict is reconstructed when any key from the
            # write set now belongs to the tenant, a restored policy exists,
            # or (empty bundle) the persistent empty-restore marker is on
            # disk. Every other rejection (in-bundle tenant mismatch, foreign
            # occupation) replays as 404. Restore events always carry
            # key_id null.
            for key_id in details.get("key_ids", []):
                raw = store.read_raw(key_id)
                if raw is not None and raw.tenant_id == tenant_id:
                    return error(409, message_for(409))
            if details.get("policy_restored") and policy_store.get(
                tenant_id
            ) is not None:
                return error(409, message_for(409))
            digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
            marker = os.path.join(
                store.data_dir, "restore-empty-" + digest + ".json"
            )
            if os.path.exists(marker):
                return error(409, message_for(409))
            return error(404, message_for(404))
        if kind == "import":
            key_id = event.key_id or details.get("key_id")
            raw = store.read_raw(key_id) if is_valid_key_id(key_id) else None
            if raw is not None and raw.tenant_id == tenant_id:
                return error(409, message_for(409))
            return error(404, message_for(404))
        # rotate (and any unknown shape): a rejected rotate means the key was
        # unknown or foreign at commit time and no version was appended.
        return error(404, message_for(404))

    if kind == "rotate":
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            # The committed version is the one whose creation time equals the
            # event timestamp; fall back to the current pointer.
            ver = None
            for candidate in key.versions:
                if candidate.created_at == event.timestamp:
                    ver = candidate
                    break
            if ver is None:
                ver = key.current
            return (
                201,
                {
                    "key_id": key_id,
                    "version": ver.version,
                    "algorithm": ver.algorithm,
                    "public_key": ver.public_key,
                    "operation_id": op_id,
                },
            )
    if kind == "batch_rotate":
        # The batch's single event carries key_id null; the request-order
        # item set is durable in details. Rebuild each item's committed
        # version (the one minted at the event timestamp, else the current
        # pointer). A key that is no longer readable makes the projection fall
        # back to operation_id-only rather than fabricating a version.
        result_items = []
        complete = True
        for one in details.get("items", []):
            key_id = one.get("key_id")
            key = (
                store.get(key_id, tenant_id)
                if is_valid_key_id(key_id)
                else None
            )
            if key is None:
                complete = False
                break
            ver = None
            for candidate in key.versions:
                if candidate.created_at == event.timestamp:
                    ver = candidate
                    break
            if ver is None:
                ver = key.current
            result_items.append(
                {
                    "key_id": key_id,
                    "version": ver.version,
                    "algorithm": ver.algorithm,
                    "public_key": ver.public_key,
                }
            )
        if complete:
            return 201, {"items": result_items, "operation_id": op_id}
    if kind == "import":
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            body = key.to_create_response()
            body["operation_id"] = op_id
            return 201, body
    if kind == "restore":
        return (
            201,
            {
                "tenant_id": tenant_id,
                "key_ids": details.get("key_ids", []),
                "policy_restored": details.get("policy_restored", False),
                "operation_id": op_id,
            },
        )
    # Cannot rebuild the projection; the mutation did commit, so keep it
    # succeeded with an operation_id-only body rather than pending forever.
    return 201, {"operation_id": op_id}


def serve(host: str, port: int, data_dir: str) -> None:
    """Run the HTTP server until interrupted."""
    audit_log = AuditLog(data_dir)
    # Key-store and restore outbox recovery run first (constructors), so a
    # half-committed mutation's files/handles are settled before the
    # operation store resolves the pending operation that wrapped it.
    store = KeyStore(data_dir, audit_log)
    policy_store = PolicyStore(data_dir, audit_log)
    coordinator = restore_mod.RestoreCoordinator(store, policy_store)
    operation_store = OperationStore(data_dir, audit_log)
    # The artifact mirrors settle next (after the outbox recovery): a
    # consistent mirror is cleaned, a fully rolled-back attempt's mirror is
    # dropped, and an unprovable scene keeps both its evidence and its
    # operation pending for a later open.
    from .artifacts import ArtifactStore

    artifact_store = ArtifactStore(data_dir, store, audit_log)
    artifact_store.settle_pending(operation_store)
    operation_store.recover_pending(
        lambda record, event: _resolve_committed_operation(
            store, policy_store, record, event
        ),
        is_parked=artifact_store.is_parked,
    )
    httpd = ThreadingHTTPServer(
        (host, port),
        make_handler(
            store, policy_store, coordinator, operation_store, artifact_store
        ),
    )
    httpd.daemon_threads = True
    try:
        httpd.serve_forever()

def _http_to_cli(http_status: int) -> int:
    return {201: 0, 200: 0, 400: 2, 403: 3, 409: 3, 404: 4}.get(
        http_status, 1
    )


def _terminal_rejection(
    op_store, store, operation, tenant_id, key_id, action,
    http_status, message,
):
    """Durably persist a bound op's terminal rejection and append it.

    CLI counterpart of the HTTP handler: the operation kind, the exact key_id
    rule, the terminal status, the complete error response and the audit
    descriptor are merged into the durable context *before* the one rejected
    event (named after the operation_id, deduped on event_id) is appended, so a
    crash and startup recovery replay this exact 403/404/409 verbatim instead
    of re-evaluating the policy or re-reading the object. Returns
    ``(http_status, body)`` for idempotent_run.
    """
    op_id = operation.operation_id
    body = {"error": message, "operation_id": op_id}
    kind = (operation.details or {}).get("kind")
    audit_key_id = (
        None if kind in ("restore", "batch_rotate")
        else (key_id if is_valid_key_id(key_id) else None)
    )
    op_store.stage_terminal(
        operation,
        http_status,
        body,
        audit={
            "action": action,
            "outcome": audit_mod.OUTCOME_REJECTED,
            "tenant_id": tenant_id,
            "key_id": audit_key_id,
        },
    )
    store.audit_attempt(
        tenant_id, audit_key_id, action, audit_mod.OUTCOME_REJECTED,
        event_id=op_id,
    )
    return http_status, body


def _provider_terminal(
    op_store, store, operation, http_status, message
):
    """Persist a bound op's provider-failure terminal and append it.

    CLI counterpart of the HTTP handler: after the Idempotency-Key is bound,
    a KMS/HSM load/contract/call/handle-delete failure (503) or a refusal of
    imported material (400) is a durable terminal -- the safe response is
    staged, one rejected event named after the operation_id is appended
    (rotate projects the request key_id, import the in-bundle key_id, restore
    null), and the op is finished, so an HTTP/CLI cross-retry replays exactly
    this result and the event is never duplicated. Raises OSError/LedgerError
    if that persistence itself fails (the caller finalizes failed(500)).
    """
    op_id = operation.operation_id
    body = {"error": message, "operation_id": op_id}
    details = operation.details or {}
    kind = details.get("kind")
    if kind == "batch_rotate":
        action = audit_mod.ACTION_BATCH_ROTATE
    elif kind == "rotate":
        action = audit_mod.ACTION_ROTATE
    else:
        action = audit_mod.ACTION_IMPORT
    audit_key_id = (
        None if kind in ("restore", "batch_rotate")
        else (
            details.get("key_id")
            if is_valid_key_id(details.get("key_id"))
            else None
        )
    )
    op_store.stage_terminal(
        operation,
        http_status,
        body,
        audit={
            "action": action,
            "outcome": audit_mod.OUTCOME_REJECTED,
            "tenant_id": operation.tenant_id,
            "key_id": audit_key_id,
        },
    )
    store.audit_attempt(
        operation.tenant_id, audit_key_id, action,
        audit_mod.OUTCOME_REJECTED, event_id=op_id,
    )
    op_store.finish(operation, operations_mod.STATUS_FAILED, http_status, body)
    return http_status, body


def _idem_key_error(key) -> bool:
    """Validate an --idempotency-key; report exit 2 when malformed."""
    if not operations_mod.is_valid_idempotency_key(key):
        _fail(
            "field idempotency_key must be 1-128 characters from "
            "A-Za-z0-9._~-", 2
        )
        return True
    return False


def _emit_operation_result(http_status: int, body: dict) -> int:
    """Print a terminal operation's body and return the CLI exit code."""
    if 200 <= http_status < 300:
        _print(body)
    else:
        # Errors contain only error and operation_id.
        print(
            json.dumps(
                {
                    "error": body.get("error", "request failed"),
                    "operation_id": body.get("operation_id"),
                },
                separators=(",", ":"),
            ),
            file=sys.stderr,
        )
    return _http_to_cli(http_status)


def _idem_serve_existing(op_store, kind, record) -> "Optional[int]":
    """Replay/conflict for a bound key.

    Returns an exit code for conflict and for a terminal replay, or None when
    the binding is new OR the operation is still pending (the caller decides
    whether to wait for a live owner or take a stranded attempt over).
    """
    if kind == "new":
        return None
    if kind == "conflict":
        return _emit_operation_result(
            409,
            {
                "error": "Idempotency-Key is already bound to a different "
                "request",
                "operation_id": record.operation_id,
            },
        )
    if record.is_terminal():
        return _emit_operation_result(record.http_status, record.response)
    return None


def _idem_wait_then_serve(op_store, record) -> int:
    """Wait for a live owner then replay its terminal, or emit 503 timed out."""
    record = op_store.await_terminal(record)
    if record.is_terminal():
        return _emit_operation_result(record.http_status, record.response)
    return _emit_operation_result(
        503,
        {
            "error": "operation timed out waiting for a lock",
            "operation_id": record.operation_id,
        },
    )


def _strand_unavailable_body(operation_id: str) -> dict:
    """Material-safe body for a mirror/strand failure; op stays pending."""
    return {
        "error": "temporary storage failure, please retry",
        "operation_id": operation_id,
    }


def _run_owned_attempt(op_store, store, artifact_store, executor, operation,
                       blocking, takeover=False) -> int:
    """Run one attempt under its mirror + cross-process claim.

    Used by the binding winner (takeover=False) and by an identical retry that
    takes a stranded pending attempt over (takeover=True). A mirror claim/
    creation failure leaves the operation pending and returns the 500/503 exit
    code without calling a provider or writing any key/handle/audit.
    """
    op_id = operation.operation_id
    if artifact_store is None:
        return _idempotent_run_body(
            op_store, store, None, executor, operation, op_id, None
        )
    from .artifacts import (
        ArtifactAlreadyTerminal,
        ArtifactStrandUnavailable,
    )

    attempt_cm = artifact_store.attempt(
        operation, blocking, takeover=takeover,
        operation_store=op_store if takeover else None,
    )
    try:
        mirror = attempt_cm.__enter__()
    except ArtifactAlreadyTerminal as already:
        # The owner reached a terminal while the claim was taken: replay its
        # fresh stored result verbatim, execute nothing.
        return _emit_operation_result(
            already.record.http_status, already.record.response
        )
    except ArtifactStrandUnavailable as exc:
        return _emit_operation_result(
            exc.http_status, _strand_unavailable_body(op_id)
        )
    except BlockingIOError:
        raise
    try:
        return _idempotent_run_body(
            op_store, store, artifact_store, executor,
            operation, op_id, mirror,
        )
    except ArtifactStrandUnavailable as exc:
        # The mirror could not be described/tied in before the first provider
        # call: keep the operation pending for a same-id retry.
        return _emit_operation_result(
            exc.http_status, _strand_unavailable_body(op_id)
        )
    finally:
        attempt_cm.__exit__(None, None, None)


def idempotent_run(op_store, store, path, tenant_id, operator, body, key,
                   validator, executor, decoder=None, artifact_store=None):
    """CLI counterpart of the HTTP idempotency guard.

    Returns a process exit code. ``validator()`` runs cheap side-effect-free
    request checks *before* the binding lookup and returns None on success or
    an ``(exit_code, message)`` refusal (a refusal is never audited and never
    consumes the key). ``decoder`` (when given) performs the side-effect-free
    but expensive validation -- bundle decryption -- *after* an already-bound
    key has been replayed/conflicted but *before* a new key is bound, so a
    wrong passphrase neither masks a replay nor consumes the key.
    ``executor(operation, mirror) -> (http_status, body)`` runs once for a new
    binding and may raise ProviderInvalidMaterial / ProviderUnavailable /
    LedgerError / LockTimeout.
    """
    if _idem_key_error(key):
        return 2
    normalized = operations_mod.normalize_body(body)

    refusal = validator()
    if refusal is not None:
        code, message = refusal
        return _fail(message, code)

    # An already-bound key replays/conflicts before the expensive decoder
    # (bundle decryption), so a bad passphrase on a retry never masks a
    # replay or consumes the key.
    peek = op_store.peek(tenant_id, operator, path, normalized, key)
    existing = _idem_serve_existing(op_store, peek.kind, peek.record)
    if existing is not None:
        return existing

    if decoder is not None:
        refusal = decoder()
        if refusal is not None:
            code, message = refusal
            return _fail(message, code)

    # begin() is authoritative for the bind (another process may have won
    # between the peek and here).
    begin = op_store.begin(tenant_id, operator, path, normalized, key)
    if begin.kind == "conflict":
        return _idem_serve_existing(op_store, "conflict", begin.record)
    if begin.kind == "replay":
        if begin.record.is_terminal():
            return _idem_serve_existing(op_store, "replay", begin.record)
        # Still pending: take a stranded attempt over immediately; if a live
        # owner (thread or process) holds the claim, wait for its terminal.
        if artifact_store is not None:
            try:
                return _run_owned_attempt(
                    op_store, store, artifact_store, executor,
                    begin.record, blocking=False, takeover=True,
                )
            except BlockingIOError:
                return _idem_wait_then_serve(op_store, begin.record)
        return _idem_wait_then_serve(op_store, begin.record)

    operation = begin.record
    return _run_owned_attempt(
        op_store, store, artifact_store, executor, operation,
        blocking=True, takeover=False,
    )


def _idempotent_run_body(op_store, store, artifact_store, executor, operation,
                         op_id, mirror):
    from .artifacts import ArtifactStrandUnavailable

    try:
        http_status, resp = executor(operation, mirror)
    except ArtifactStrandUnavailable as exc:
        # The mirror could not be described/tied in before the first provider
        # call: nothing committed, keep the operation pending for a same-id
        # retry (exit 1).
        return _emit_operation_result(
            exc.http_status, _strand_unavailable_body(op_id)

        )
    except LockTimeout:
        body_err = {
            "error": "operation timed out waiting for a lock",
            "operation_id": op_id,
        }
        op_store.finish(
            operation, operations_mod.STATUS_TIMED_OUT, 503, body_err
        )
        return _emit_operation_result(503, body_err)
    except ProviderInvalidMaterial as exc:
        try:
            http_status, body_err = _provider_terminal(
                op_store, store, operation, 400, str(exc)
            )
            return _emit_operation_result(http_status, body_err)
        except (OSError, LedgerError) as persist_exc:
            body_err = {
                "error": "audit ledger failure: %s" % persist_exc,
                "operation_id": op_id,
            }
            op_store.finish(
                operation, operations_mod.STATUS_FAILED, 500, body_err
            )
            return _emit_operation_result(500, body_err)
    except ProviderReconnectPending:
        # The provider was never effectively called (gate timeout or a
        # displaced provider_id): the store/restore abort path already removed
        # the empty journal and minted no handle. Reset the mirror to a clean
        # bound strand and leave the operation PENDING for a same-id retry,
        # answering the fixed safe 503 (exit 1) without a duplicate event.
        if mirror is not None:
            try:
                mirror.reset_for_pending_retry()
            except OSError:
                pass
        return _emit_operation_result(
            503,
            {
                "error": "key management provider is unavailable",
                "operation_id": op_id,
            },
        )
    except ProviderUnavailable:
        try:
            http_status, body_err = _provider_terminal(
                op_store, store, operation, 503,
                "key management provider is unavailable",
            )
            return _emit_operation_result(http_status, body_err)
        except (OSError, LedgerError) as persist_exc:
            body_err = {
                "error": "audit ledger failure: %s" % persist_exc,
                "operation_id": op_id,
            }
            op_store.finish(
                operation, operations_mod.STATUS_FAILED, 500, body_err
            )
            return _emit_operation_result(500, body_err)
    except OSError as exc:
        # A pre-commit staging/write failure happened before the commit-point
        # append: file and handles were rolled back, nothing committed.
        # Finalize failed(500).
        body_err = {
            "error": "audit ledger failure: %s" % exc,
            "operation_id": op_id,
        }
        op_store.finish(operation, operations_mod.STATUS_FAILED, 500, body_err)
        return _emit_operation_result(500, body_err)
    except LedgerError as exc:
        body_err = {
            "error": "audit ledger failure: %s" % exc,
            "operation_id": op_id,
        }
        op_store.finish(operation, operations_mod.STATUS_FAILED, 500, body_err)
        return _emit_operation_result(500, body_err)
    resp = dict(resp)
    resp["operation_id"] = op_id
    state = operations_mod.state_for_http_status(http_status)
    op_store.finish(operation, state, http_status, resp)
    if artifact_store is not None and mirror is not None:
        # Committed: verified ownership then dropped; uncommitted: dropped
        # only once every rollback artifact is gone. A mirror that cannot be
        # verified survives for the next startup.
        artifact_store.after_terminal(mirror)
    return _emit_operation_result(http_status, resp)


def main(argv: Optional[List[str]] = None) -> int:
    """CLI entry point; returns a process exit code.

    A KMS/HSM backend failure maps to exit code 1 (HTTP 503) with a generic
    message; malformed imported material maps to exit code 2 (HTTP 400).
    """
    try:
        return _run(argv)
    except ProviderInvalidMaterial as exc:
        return _fail(str(exc), 2)
    except ProviderUnavailable:
        # Generic wording: never print a handle or material in the error.
        return _fail("key management provider is unavailable", 1)


def _run(argv: Optional[List[str]] = None) -> int:
    """Parse and execute one CLI command."""
    args = build_parser().parse_args(argv)

    if args.command == "serve":
        serve(args.host, args.port, args.data_dir)
        return 0

        _print(record.to_get_response())
    else:
        _print(record.current.to_version_response(args.key_id))
    return 0

if args.command == "rotate":
    # The Idempotency-Key is validated before any other parameter (and
    # before the binding/execution): a malformed key is an exit-2 error
    # with no audit event, operation record, key change or provider
    # handle -- exactly like the HTTP endpoint.
    if _idem_key_error(args.idempotency_key):
        return 2
    if not args.tenant_id:
        return _fail("field tenant_id must be a non-empty string", 2)
    if not is_valid_key_id(args.key_id):
        return _fail("field key_id must be a UUID4", 2)
    if args.algorithm not in SUPPORTED_ALGORITHMS:
        return _fail(
            "unsupported value for field algorithm: %r (supported: %s)"
            % (args.algorithm, ", ".join(SUPPORTED_ALGORITHMS)),
            2,
        )

    body = {
        "tenant_id": args.tenant_id,
        "algorithm": args.algorithm,
    }
    path = "/v1/keys/%s/rotate" % args.key_id

    def execute(operation, mirror=None):
        # Kind/exact key_id are durable before the authorization check so
        # a 403 terminal replays from context alone after a crash.
        op_store.update_details(
            operation,
            {"kind": "rotate", "key_id": args.key_id,
